int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags)
{
    struct sock *sk = sock->sk;
    int copied = 0;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (flags & MSG_OOB)
        return -EOPNOTSUPP;

    if (sock->type == SOCK_DGRAM) {
        struct sk_buff *skb;
        skb = skb_dequeue(&sk->sk_receive_queue);
        if (!skb)
            return -EAGAIN;

        copied = skb->len;
        if (copied > len)
            copied = len;

        memcpy(msg->msg_name, skb->cb, sizeof(skb->cb));
        msg->msg_namelen = sizeof(skb->cb);
        memcpy(msg->msg_control, skb->cb + sizeof(skb->cb),
               skb->len - sizeof(skb->cb));
        msg->msg_controllen = skb->len - sizeof(skb->cb);
        memcpy(msg->msg_iov->iov_base, skb->data, copied);
        msg->msg_iov->iov_len = copied;

        skb_pull(skb, copied);
        kfree_skb(skb);
    } else {
        struct sk_buff *skb, *head;
        int copied = 0;
        int target = len;

        while (target > 0 && (skb = skb_peek(&sk->sk_receive_queue))) {
            head = skb;
            do {
                int copy = min_t(int, target, skb->len);
                int offset = 0;
                int err;

                if (skb == head)
                    skb_pull(skb, skb->len);

                if (copy <= 0)
                    break;

                err = skb_copy_datagram_iovec(skb, offset, msg->msg_iov, copy);
                if (err < 0)
                    return err;

                copied += copy;
                target -= copy;
            } while ((skb = skb_peek(&sk->sk_receive_queue)));
        }
    }

    return copied;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags)
{
    struct sock *sk = sock->sk;
    int error;
    int data_len;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (sock->type == SOCK_DGRAM)
        error = sock->ops->recvmsg(iocb, msg, len, flags, &data_len);
    else
        error = sock->ops->recvmsg(iocb, msg, len, flags, &data_len);

    if (error < 0)
        return error;

    if (data_len > 0) {
        if (msg->msg_name && msg->msg_namelen) {
            struct sockaddr *addr = (struct sockaddr *)msg->msg_name;
            memcpy(addr, sk->sk_socket->sk_daddr, sizeof(*addr));
        }
        sock->ops->release_skb(sk, msg->msg_iocb->ki_pos, data_len);
    }

    return data_len;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    int ret;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (sock->type & SOCK_OOB)
        flags |= MSG_OOB;

    ret = sk->ops->recvmsg(iocb, sk, msg, len, flags, NULL);

    if (ret > 0) {
        if (msg->msg_name && msg->msg_namelen) {
            memcpy(msg->msg_name, &sock->uaddr, sock->uaddr_len);
        }
        msg->msg_flags &= ~MSG_TRUNC;
    }

    return ret;
}

#include <linux/socket.h>
#include <linux/uio.h>
#include <linux/slab.h>
#include <linux/net.h>

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    int copied = 0;
    int err = 0;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (flags & MSG_OOB) {
        err = sock_recv_dgram_oob(sk, msg, len, flags);
        if (err >= 0)
            copied = err;
    } else {
        struct sk_buff *skb;
        while (len > 0) {
            skb = skb_dequeue(&sk->sk_receive_queue);
            if (!skb) {
                if (copied == 0)
                    return -EAGAIN;
                break;
            }

            if (flags & MSG_PEEK) {
                err = skb_linearize(skb);
                if (err)
                    continue;
            }

            err = skb_copy_datagram_msg(skb, 0, msg, len);
            if (err < 0) {
                kfree_skb(skb);
                continue;
            }

            copied += err;
            len -= err;
            if (flags & MSG_PEEK)
                skb_queue_head(&sk->sk_receive_queue, skb);
            else
                kfree_skb(skb);

            if ((flags & MSG_WAITALL) && len > 0)
                continue;
            break;
        }
    }

    if (copied > 0)
        return copied;
    return (err < 0) ? err : -ENOMSG;
}
